using namespace std;

struct PT {
    int x, y;

    PT(int x = 0, int y = 0) : x(x), y(y) {}

    PT operator+(const PT& other) const {
        return PT(x + other.x, y + other.y);
    }

    bool operator<(const PT& other) const {
        return tie(x, y) < tie(other.x, other.y);
    }

    bool operator!=(const PT& other) const {
        return x != other.x || y != other.y;
    }
};

struct CustomHash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(long long x) const {
        static const uint64_t seed =
            chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(static_cast<uint64_t>(x) + seed);
    }
};

void solve() {
    int n;
    cin >> n;

    vector<PT> points(n);
    PT center;
    map<PT, int> parity;

    for (PT& point : points) {
        cin >> point.x >> point.y;
        center = center + point;
        point.x *= n;
        point.y *= n;
        parity[point] ^= 1;
    }

    for (const PT& point : points) {
        PT reflected(2 * center.x - point.x, 2 * center.y - point.y);
        parity[reflected] ^= 1;
    }

    vector<PT> p;
    p.reserve(parity.size());

    for (const auto& [point, value] : parity) {
        if (point != center && value) {
            p.push_back(point);
        }
    }

    if (p.empty()) {
        cout << -1 << '\n';
        return;
    }

    vector<pair<int, int>> directions;
    directions.reserve(p.size() - 1);

    for (size_t i = 1; i < p.size(); ++i) {
        int dx = p[0].x - p[i].x;
        int dy = p[0].y - p[i].y;

        if (dy < 0 || (dy == 0 && dx < 0)) {
            dx = -dx;
            dy = -dy;
        }

        int g = std::gcd(abs(dx), abs(dy));
        dx /= g;
        dy /= g;
        directions.emplace_back(dx, dy);
    }

    sort(directions.begin(), directions.end());
    directions.erase(unique(directions.begin(), directions.end()),
                     directions.end());

    unordered_set<long long, CustomHash> oddLines;
    oddLines.reserve(p.size() * 2 + 1);

    int result = 0;

    for (const auto& [dx, dy] : directions) {
        oddLines.clear();

        for (const PT& point : p) {
            long long line =
                static_cast<long long>(dx) * point.y -
                static_cast<long long>(dy) * point.x;

            auto [it, inserted] = oddLines.insert(line);
            if (!inserted) {
                oddLines.erase(it);
            }
        }

        if (oddLines.empty()) {
            ++result;
        }
    }

    cout << result << '\n';
}

